## 3. CODIFICAÇÃO EM JAVA

```java
import java.util.*;
import java.io.*;

public class Main {
    static int[] parent, size, head, tail, nxt, P;
    static long[] sum, ans;
    static boolean[] proc;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static void freeze(int root) {
        int cur = head[root];
        long val = sum[root];
        while (cur != 0) {
            ans[cur] = val;
            int nextCell = nxt[cur];
            nxt[cur] = 0;
            cur = nextCell;
        }
        head[root] = 0;
        tail[root] = 0;
    }

    static int union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return ra;

        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }

        parent[rb] = ra;
        size[ra] += size[rb];
        sum[ra] += sum[rb];

        if (head[rb] != 0) {
            if (head[ra] == 0) {
                head[ra] = head[rb];
                tail[ra] = tail[rb];
            } else {
                nxt[tail[ra]] = head[rb];
                tail[ra] = tail[rb];
            }
        }

        head[rb] = 0;
        tail[rb] = 0;
        return ra;
    }

    static void processNeighbor(int id, int nid, long p) {
        if (!proc[nid]) return;

        int root = find(nid);
        int idRoot = find(id);

        if (root == idRoot) return;

        if (head[root] != 0 && sum[root] < p) {
            freeze(root);
        }

        union(idRoot, root);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = N * M;

        P = new int[K];
        for (int r = 0; r < N; r++) {
            st = new StringTokenizer(br.readLine());
            for (int c = 0; c < M; c++) {
                P[r * M + c] = Integer.parseInt(st.nextToken());
            }
        }

        parent = new int[K];
        size = new int[K];
        head = new int[K];
        tail = new int[K];
        nxt = new int[K];
        sum = new long[K];
        ans = new long[K];
        proc = new boolean[K];

        for (int i = 0; i < K; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        final int SHIFT = 20;
        final long MASK = (1L << SHIFT) - 1;

        long[] keys = new long[K];
        for (int i = 0; i < K; i++) {
            keys[i] = ((long) P[i] << SHIFT) | i;
        }

        Arrays.sort(keys);

        for (long key : keys) {
            int id = (int) (key & MASK);
            long p = P[id];

            proc[id] = true;
            parent[id] = id;
            size[id] = 1;
            sum[id] = p;
            head[id] = id;
            tail[id] = id;
            nxt[id] = 0;

            int r = id / M;
            int c = id % M;

            if (r > 0) processNeighbor(id, id - M, p);
            if (r + 1 < N) processNeighbor(id, id + M, p);
            if (c > 0) processNeighbor(id, id - 1, p);
            if (c + 1 < M) processNeighbor(id, id + 1, p);
        }

        for (int i = 0; i < K; i++) {
            if (ans[i] == 0) {
                ans[i] = sum[find(i)];
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                if (c > 0) sb.append(' ');
                sb.append(ans[r * M + c]);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }
}
```

